from __future__ import annotations
import base64
import shutil
from datetime import datetime
from pathlib import Path

MODULE="alliance_autonomous_student_v430.py"
REG="alliance_optional_property_modules.py"
DATA=""

def chk(p):
    compile(p.read_text(encoding="utf-8"), str(p), "exec")

def main():
    r=Path.cwd()
    required=[
        "alliance_cre_academy_v400.py",
        "alliance_cre_academy_v401.py",
        "alliance_cre_academy_v402.py",
        "alliance_cre_championship_v410.py",
        "alliance_automation_machine_v420.py",
        "alliance_automation_truth_escalator_v421.py",
        "alliance_automation_closure_v422.py",
        "alliance_automation_grammar_rescue_v423.py",
        "alliance_acquisition_intent_closure_v425.py",
        REG,
    ]
    missing=[x for x in required if not (r/x).exists()]
    if missing:
        raise SystemExit("Missing cumulative files: "+", ".join(missing))

    # Verify V4 is genuinely closed before installing a learner that consumes it.
    v425=(r/"alliance_acquisition_intent_closure_v425.py").read_text(encoding="utf-8")
    if "AUTOMATED_INDEPENDENT_V4_HOLD" not in v425:
        raise SystemExit("Current 4.2.5 source shape unexpected; refusing blind install.")

    reg=r/REG
    old=reg.read_text(encoding="utf-8")
    bak=r/f"{REG}.before-v430-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"
    shutil.copy2(reg,bak)

    (r/MODULE).write_text(base64.b64decode(DATA).decode(),encoding="utf-8")

    marker="# FOUNDATION 4.3.0 - Alliance Autonomous Student V5"
    if marker not in old:
        pos=old.rfind("    return result")
        if pos<0:
            raise SystemExit("Registrar return not found; no changes made.")
        block=r"""
    # FOUNDATION 4.3.0 - Alliance Autonomous Student V5
    # V4 is closed training data. Fresh V5 is frozen only after regression gates pass.
    try:
        if _route_exists(app, "/api/property-brain/autonomous-v430/status"):
            result["autonomous_v430"] = {"status":"ALREADY_REGISTERED","route":"/property-brain/autonomous-v430","error":None}
        else:
            import alliance_autonomous_student_v430 as autonomous_v430
            result["autonomous_v430"] = {**autonomous_v430.register(core), "error": None}
    except Exception as exc:
        result["autonomous_v430"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","route":"/property-brain/autonomous-v430","fail_safe":True}

"""
        reg.write_text(old[:pos]+block+old[pos:],encoding="utf-8")

    chk(r/MODULE)
    chk(reg)

    txt=reg.read_text(encoding="utf-8")
    checks={
        "v402":"academy_v402" in txt,
        "v410":"championship_v410" in txt,
        "v420":"automation_v420" in txt,
        "v421":"automation_v421" in txt,
        "v422":"automation_v422" in txt,
        "v423":"automation_v423" in txt,
        "v425":"automation_v425" in txt,
        "v430":"autonomous_v430" in txt,
    }
    if not all(checks.values()):
        raise SystemExit("Cumulative verification failed: "+repr(checks))

    print("Alliance Autonomous Student 4.3 installed")
    print("V4 remains immutable and is used only as closed training data")
    print("Legacy + lesson regression gates run automatically")
    print("Fresh V5 freezes only if training gate passes")
    print("V5 uses untouched blind IDs only")
    print("Independent V5 truth stack excludes Student 4.3")
    print("Production/WhatsApp/Gold writes: 0")
    print("Dashboard: /property-brain/autonomous-v430")
    print("Backup:",bak)

if __name__=="__main__":
    main()
